     \node[] (4) at (1,0) {$1$};
      \node[] (5) at (2,0) {$2$};


    \node[] (1a) at (-1,-0.5) {$-1$};
    \node[] (2a) at (0,-.5) {$0$};
    \node[] (3a) at (1,-.5) {$1$};

